<div class="page-heading"><p class="eyebrow">Knowledge analytics</p><h1>Reports</h1><p>Search demand, documentation gaps, and article feedback.</p></div><?php require base_path('views/admin/_nav.php'); ?><div class="report-section panel"><div class="panel-heading"><div><h2>Search analytics and documentation gaps</h2><small>Zero-result searches indicate unmet documentation demand.</small></div></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Query</th><th>Searches</th><th>Average results</th><th>Zero results</th><th>Last searched</th></tr></thead><tbody><?php foreach($searches as $row):?><tr><td><strong><?=e($row['query'])?></strong></td><td><?=(int)$row['searches']?></td><td><?=e($row['avg_results'])?></td><td><?php if($row['zero_results']):?><span class="badge text-bg-warning"><?=(int)$row['zero_results']?> gap<?= $row['zero_results']==1?'':'s'?></span><?php else:?><span class="text-secondary">0</span><?php endif;?></td><td><?=date('M j, Y H:i',strtotime($row['last_searched']))?></td></tr><?php endforeach;?><?php if(!$searches):?><tr><td colspan="5" class="empty-table">No searches have been logged.</td></tr><?php endif;?></tbody></table></div></div><div class="admin-columns mt-3"><section class="panel"><div class="panel-heading"><h2>Feedback report</h2></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Article</th><th>Helpful</th><th>Not helpful</th></tr></thead><tbody><?php foreach($feedback as $row):?><tr><td><a href="/articles/<?=$row['id']?>"><?=e($row['title'])?></a></td><td><?=(int)$row['helpful']?></td><td><?=(int)$row['unhelpful']?></td></tr><?php endforeach;?><?php if(!$feedback):?><tr><td colspan="3" class="empty-table">No feedback submitted.</td></tr><?php endif;?></tbody></table></div></section><aside class="panel"><div class="panel-heading"><h2>Improvement comments</h2></div><div class="comment-list"><?php foreach($comments as $row):?><div><p><?=e($row['reason'])?></p><a href="/articles/<?=$row['article_id']?>"><?=e($row['title'])?></a><small><?=e($row['user_name']??'Unknown')?> · <?=date('M j, Y',strtotime($row['created_at']))?></small></div><?php endforeach;?><?php if(!$comments):?><p class="text-secondary small">No improvement comments submitted.</p><?php endif;?></div></aside></div>
